    receive() external payable {}
    function run(address logAddr, uint val) public {
        require(val < type(uint256).max);
        c.SetLogFile(logAddr); if (__ESBMC_reverted()) return;
        c.SetMinSum(val); if (__ESBMC_reverted()) return;
        uint before = c.MinSum(); if (__ESBMC_reverted()) return;
        c.Initialized(); if (__ESBMC_reverted()) return;
        bool reverted;
        c.SetMinSum(val + 1); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        assert(reverted && c.MinSum() == before);
