pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MONEY_BOX c;

    function setUp() public {
        c = new MONEY_BOX();
    }

    function _run(address logAddr, uint256 val) internal {
        vm.assume(val < type(uint256).max);
        try c.SetLogFile(logAddr) {} catch { return; }
        try c.SetMinSum(val) {} catch { return; }
        uint256 before;
        try c.MinSum() returns (uint256 __r) { before = __r; } catch { return; }
        try c.Initialized() {} catch { return; }
        bool reverted;
        try c.SetMinSum(val + 1) { reverted = false; }
        catch { reverted = true; }
        assertTrue(reverted && c.MinSum() == before);
    }

    function testFuzz_run(address logAddr, uint256 val) public {
        vm.assume(logAddr.code.length == 0 && uint160(logAddr) > 0xffff && logAddr != address(this) && logAddr != address(c) && logAddr != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && logAddr != 0x000000000000000000636F6e736F6c652e6c6f67 && logAddr != 0x4e59b44847b379578588920cA78FbF26c0B4956C && logAddr != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(logAddr, val);
    }

    receive() external payable {}
}
